from ipaddress import IPv4Network

def task_func(ip_range):
    network = IPv4Network(ip_range)
    results = {}
    for ip in network:
        ip_str = str(ip)
        try:
            subprocess.check_call(['ping', '-c', '1', '-W', '1', ip_str], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            results[ip_str] = True
        except subprocess.CalledProcessError:
            results[ip_str] = False
